{"results": [{"id": "hp_doc_3a19a43569920a8719a99a39b97f77f743208114ce7005dc96243eeba5e34d91", "title": "Traveller (role-playing game)", "text": "Traveller is a series of related science fiction role-playing games, the first published in 1977 by Game Designers' Workshop. Marc W. Miller designed \"Traveller\" with help from Frank Chadwick, John Harshman, and Loren K. Wiseman.", "score": 17.4442}, {"id": "hp_doc_24807fa41d7e910fc09f0542ca7d4b1ea923f73b5d3bd22e1624f0b560f8d920", "title": "Anuman", "text": "Anuman Interactive SA is a French video game publisher and distributor. They publish games for formats including PC, Mac, interactive-DVD, Nintendo DS and Wii, PlayStation Portable and iPhone. In addition to their own brand they publish games under the Microïds label as well as the Microïds Games For All brand.", "score": 12.6297}, {"id": "hp_doc_fef067bf8067902046c66015487210b7fee728eb513f83cb5e3b86c62280098d", "title": "Game Designers' Workshop", "text": "Game Designers' Workshop (GDW) was a wargame and role-playing game publisher from 1973 to 1996. Many of their games are now carried by other publishers.", "score": 12.4689}], "remaining_searches": 2}
